WITH matched_keys AS (SELECT city FROM stores EXCEPT SELECT city FROM stores WHERE opened_date <= '2024-09-01'), verified AS (SELECT s.* FROM stores s JOIN matched_keys k ON s.city = k.city) SELECT CASE WHEN sqft >= 16744 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, COUNT(*) FILTER (WHERE city = 'Bangkok') AS bangkok_rows, SUM(CASE WHEN region = 'Central' THEN sqft ELSE 0 END) AS central_sqft, APPROX_PERCENTILE(sqft, ARRAY(0.25, 0.5, 0.75)) AS sqft_quartiles, SUM(CASE WHEN city = 'Bangkok' THEN sqft ELSE 0 END) AS bangkok_sqft FROM verified GROUP BY CUBE (CASE WHEN sqft >= 16744 THEN 'HIGH' ELSE 'LOW' END) HAVING SUM(CASE WHEN city = 'Bangkok' THEN sqft ELSE 0 END) > 0 ORDER BY bangkok_rows
